<!doctype html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>مدرسة طموح الإلكترونية | دروس تقوية أونلاين</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root{--navy:#21133d;--purple:#59369b;--coral:#f4674a;--mint:#1d9b69;--sun:#ffc857;--paper:#fffdfa;--soft:#fff4ec;--ink:#241432;--muted:#71647d;--line:#ebdfeb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Cairo,Arial,sans-serif;line-height:1.7}a{text-decoration:none;color:inherit}.container{width:min(1140px,calc(100% - 36px));margin:auto}.topbar{position:sticky;top:0;z-index:50;background:#fffdfaf2;backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.nav{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:12px;font-size:20px;font-weight:800}.brand img{width:48px;height:48px;border-radius:14px;object-fit:cover}.brand-mark{width:42px;height:42px;display:grid;place-items:center;background:linear-gradient(140deg,var(--coral),#e94b79);color:#fff;border-radius:14px 14px 5px 14px;font-size:21px}.brand small{display:block;color:var(--muted);font-size:10px;font-weight:500;margin-top:-3px}.links{display:flex;align-items:center;gap:26px}.links a{font-size:13px;font-weight:700;color:#594b64}.links a:hover,.links a.active{color:var(--coral)}.actions{display:flex;gap:9px;align-items:center}.button{display:inline-block;border:0;border-radius:99px;padding:11px 19px;background:var(--coral);color:#fff;font:700 13px Cairo;cursor:pointer;transition:.2s}.button:hover{transform:translateY(-2px);background:#df4e33}.button.ghost{background:transparent;color:var(--ink)}.menu-button{display:none;width:43px;height:43px;place-items:center;border:0;border-radius:12px;background:var(--navy);color:#fff;font-size:24px;cursor:pointer}

    /* ===== Hero — نسخة مُصلَّحة: صورة خلفية كاملة بدل العمودين ===== */
    .hero{position:relative;min-height:600px;display:flex;align-items:center;color:#fff;
      background:
        linear-gradient(90deg,rgba(24,14,44,.95) 0%,rgba(33,19,61,.86) 45%,rgba(33,19,61,.42) 78%,rgba(33,19,61,.2) 100%),
        url("https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1600&q=85") center/cover no-repeat;
      padding:80px 0}
    .hero::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 60%,rgba(20,11,38,.55));pointer-events:none}
    .hero .container{position:relative;z-index:1}
    .hero-inner{max-width:640px;margin:0 auto;text-align:center}
    .badge{display:inline-block;background:#ffffff18;border:1px solid #ffffff25;border-radius:99px;padding:6px 14px;color:#ffe4a4;font-size:12px;font-weight:700;backdrop-filter:blur(6px)}
    .hero h1{font-size:52px;line-height:1.35;margin:18px 0;text-shadow:0 4px 22px #140a2680}
    .hero h1 span{color:var(--sun)}
    .hero p{max-width:520px;margin:0 auto;color:#e3d8ee;font-size:15px;text-shadow:0 2px 12px #140a2690}
    .hero-actions{display:flex;justify-content:center;gap:12px;margin-top:30px}
    .outline{border:1px solid #ffffff75;border-radius:99px;padding:10px 19px;font-size:13px;font-weight:700}

    .strip{margin-top:-58px;position:relative;z-index:2}.stats{background:#fff;border:1px solid var(--line);border-radius:22px;display:grid;grid-template-columns:repeat(4,1fr);padding:24px;box-shadow:0 20px 45px #2616471f}.stat{padding:0 20px;border-left:1px solid var(--line)}.stat:last-child{border:0}.stat strong{display:block;font-size:21px;color:var(--purple)}.stat span{font-size:11px;color:var(--muted)}section{padding:88px 0}.section-head{text-align:center;max-width:650px;margin:0 auto 40px}.eyebrow{display:inline-block;padding:5px 13px;border-radius:99px;background:#ffeadf;color:#c7462d;font-size:11px;font-weight:800}.section-head h2{font-size:31px;line-height:1.45;margin:12px 0}.section-head h2 span{color:var(--coral)}.section-head p{font-size:13px;color:var(--muted);margin:0}.steps{max-width:760px;margin:auto}.step{display:flex;gap:17px;align-items:flex-start;padding:0 0 22px}.number{flex:0 0 52px;height:52px;display:grid;place-items:center;border-radius:50%;background:var(--coral);color:#fff;font-size:19px;font-weight:800}.step:nth-child(2) .number{background:var(--mint)}.step:nth-child(3) .number{background:var(--sun);color:var(--ink)}.step:nth-child(4) .number{background:var(--purple)}.step-body{flex:1;background:#fff;border:1px solid var(--line);border-radius:18px;padding:15px 19px}.step-body h3{font-size:16px;margin:0 0 4px}.step-body p{font-size:12px;color:var(--muted);margin:0}.subjects{background:var(--soft)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:#fff;border:1px solid var(--line);border-radius:23px 23px 6px 23px;padding:23px;transition:.2s}.card:hover{transform:translateY(-5px);box-shadow:0 18px 32px #2d19451c}.icon{width:50px;height:50px;display:grid;place-items:center;background:var(--coral);border-radius:18px 18px 18px 5px;color:#fff;font-weight:800;font-size:21px}.card:nth-child(2) .icon{background:var(--mint)}.card:nth-child(3) .icon{background:var(--purple)}.card h3{font-size:18px;margin:16px 0 5px}.card p{font-size:12px;color:var(--muted);margin:0 0 14px}.card a{color:#cf462d;font-size:12px;font-weight:800}.teachers{background:#fff9f3}.teacher-photo{width:100px;height:100px;display:grid;place-items:center;border-radius:50%;background:linear-gradient(135deg,#ffdfd4,#ffc857);font-size:29px;font-weight:800;color:var(--navy);margin:0 auto 16px;object-fit:cover;overflow:hidden}.teacher-photo img{width:100%;height:100%;border-radius:50%;object-fit:cover}.teacher-card:nth-child(2) .teacher-photo{background:linear-gradient(135deg,#d9f4e7,#7dd8a9)}.teacher-card:nth-child(3) .teacher-photo{background:linear-gradient(135deg,#eadcff,#ba92ec)}.teacher-card{text-align:center}.teacher-card h3{margin:0 0 5px}.teacher-card small{color:#c74832;font-weight:800;display:block;margin-bottom:8px}.teacher-card p{margin:8px 0}.teacher-card .tag{display:inline-block;background:#fff3e2;border-radius:99px;padding:4px 10px;font-size:10px;font-weight:800}.reviews{background:linear-gradient(180deg,#22143f,#1b1032);color:#fff}.reviews .section-head h2{color:#fff}.reviews .section-head p{color:#d7cbe4}.reviews .eyebrow{background:#ffffff1a;color:#fff}.reviews .grid{gap:22px}.review{position:relative;border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(255,255,255,.14),rgba(255,255,255,.07));border-radius:28px 28px 10px 28px;padding:26px;box-shadow:0 16px 36px #0a04147a}.review::before{content:"“";position:absolute;top:14px;left:20px;color:#ffc857;font-size:46px;line-height:1;opacity:.9}.review:hover{transform:translateY(-5px);box-shadow:0 24px 44px #0a0414a3}.stars{color:#f7b822;letter-spacing:2px;font-size:18px;margin-bottom:12px}.review p{font-size:13px;min-height:78px;line-height:1.9;color:#f8f2ff}.review b{font-size:13px;color:#fff;display:block;margin-top:12px}.review small{display:block;color:#d7cbe4;font-size:11px}.cta{background:var(--mint);border-radius:28px 28px 8px 28px;padding:41px 45px;display:flex;justify-content:space-between;align-items:center;gap:20px;color:#fff}.cta h2{margin:0;font-size:27px}.cta p{margin:4px 0 0;font-size:13px;color:#e5f9ef}.cta .button{background:#fff;color:var(--mint)}footer{background:#180e2d;color:#d8cee5;padding:30px 0}.footer{display:flex;align-items:center;justify-content:space-between;gap:20px}.footer p,.footer span{font-size:11px;margin:0}
    @media(max-width:760px){.nav{min-height:68px}.brand{font-size:16px}.links{display:none;position:absolute;top:68px;right:18px;left:18px;padding:10px;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 20px 35px #21133d24}.links.open{display:grid;gap:3px}.links a{padding:10px 12px;border-radius:9px}.links a:hover{background:#fff0e9}.actions{display:none}.menu-button{display:grid}.hero{min-height:480px;padding:56px 0 80px;background-position:65% center}.hero h1{font-size:32px}.hero p{font-size:14px}.hero-inner{max-width:100%}.strip{margin-top:-46px}.stats{grid-template-columns:1fr 1fr;padding:13px}.stat{padding:12px;border-left:1px solid var(--line)}.stat:nth-child(2),.stat:nth-child(4){border:0}.grid{grid-template-columns:1fr}.section-head h2{font-size:27px}section{padding:62px 0}.cta{padding:31px 25px;display:block}.cta .button{margin-top:18px}.footer{display:block}.footer p{margin:13px 0}.hero-actions{flex-wrap:wrap}}
  </style>
</head>
<body>
  @include('partials.site-nav')
  <main id="home">
    <section class="hero"><div class="container">
      <div class="hero-inner">
        <span class="badge">من فلسطين، لكل طالب فلسطيني</span>
        <h1>تعليمك اليوم،<br><span>هو إنجازك غدًا</span></h1>
        <p>حصص مباشرة، مدرسون متخصصون، وخطة واضحة تساعدك على فهم المنهاج الفلسطيني بثقة ومن أي مكان.</p>
        <div class="hero-actions"><a class="button" href="{{ route('register') }}">ابدأ رحلتك الآن</a><a class="outline" href="{{ route('catalog') }}">تصفح المواد</a></div>
      </div>
    </div></section>
    <div class="strip"><div class="container stats"><div class="stat"><strong>+1200</strong><span>طالب يتعلم معنا بثقة</span></div><div class="stat"><strong>35+</strong><span>مادة ودورة</span></div><div class="stat"><strong>28</strong><span>مدرسًا معتمدًا</span></div><div class="stat"><strong>4.9</strong><span>تقييم الطلاب</span></div></div></div>
    <section id="how"><div class="container"><div class="section-head"><span class="eyebrow">بكل بساطة</span><h2>رحلتك معنا في <span>أربع خطوات</span></h2><p>سجّل، اختر ما يناسبك، ثم ابدأ التعلم ضمن تجربة واضحة وسهلة.</p></div><div class="steps"><article class="step"><span class="number">١</span><div class="step-body"><h3>أنشئ حسابك</h3><p>سجّل بياناتك وحدد المرحلة الدراسية التي تناسبك.</p></div></article><article class="step"><span class="number">٢</span><div class="step-body"><h3>اختر موادك</h3><p>تصفح المواد والمدرسين واختر خطتك التعليمية.</p></div></article><article class="step"><span class="number">٣</span><div class="step-body"><h3>أكمل الاشتراك</h3><p>اختر طريقة الدفع المتاحة وأرسل مرجع العملية.</p></div></article><article class="step"><span class="number">٤</span><div class="step-body"><h3>ابدأ التعلم</h3><p>تابع حصصك المباشرة ومحتواك المنظم من حسابك.</p></div></article></div></div></section>
    <section class="subjects"><div class="container"><div class="section-head"><span class="eyebrow">المنهاج الفلسطيني</span><h2>موادك الدراسية، <span>بشكل أوضح</span></h2><p>شرح مبسّط، مراجعات، وتدريبات تساعدك على التقدم بثقة.</p></div><div class="grid"><article class="card"><div class="icon">∑</div><h3>الرياضيات</h3><p>فهم القوانين وحل المسائل بخطوات عملية وواضحة.</p><a href="{{ route('catalog') }}">عرض المواد ←</a></article><article class="card"><div class="icon">Aa</div><h3>اللغة الإنجليزية</h3><p>تأسيس ومراجعة ومهارات امتحانية بخطة منظمة.</p><a href="{{ route('catalog') }}">عرض المواد ←</a></article><article class="card"><div class="icon">◈</div><h3>العلوم والفيزياء</h3><p>شرح المفاهيم وتطبيقها على الأسئلة السابقة.</p><a href="{{ route('catalog') }}">عرض المواد ←</a></article></div></div></section>
    <section class="teachers" id="teachers"><div class="container"><div class="section-head"><span class="eyebrow">خبرة تساندك</span><h2>مدرسون يشرحون لك <span>بطريقتك</span></h2><p>مدرسون متخصصون، وشرح قريب من الطالب، ومتابعة حقيقية لتقدمك.</p><a href="{{ route('teachers') }}" class="button" style="margin-top:18px">عرض جميع المدرسين ←</a></div><div class="grid" id="home-teachers"><p>جارٍ تحميل المدرسين...</p></div></div></section>
    <section class="reviews" id="reviews"><div class="container"><div class="section-head"><span class="eyebrow">من تجربة طلابنا</span><h2>كلمات صغيرة، <span>أثر كبير</span></h2><p>تجربة منظمة تجعل المادة والمدرس وخطتك الدراسية أوضح من البداية.</p></div><div class="grid"><article class="card review"><div class="stars">★★★★★</div><p>«الشرح مرتب، وصرت أعرف بالضبط ماذا أراجع قبل كل حصة.»</p><b>ليان س.</b><small>طالبة في الصف العاشر</small></article><article class="card review"><div class="stars">★★★★★</div><p>«أكثر شيء مفيد أن الجدول وخطة المادة واضحان من البداية.»</p><b>أحمد م.</b><small>طالب توجيهي</small></article><article class="card review"><div class="stars">★★★★★</div><p>«كولي أمر، أقدر أعرف المادة والمدرس وتفاصيل الاشتراك بسهولة.»</p><b>أم يزن</b><small>وليّة أمر</small></article></div></div></section>
    <section><div class="container"><div class="cta"><div><h2>مستعد تبدأ؟</h2><p>مكانك معنا، وخطوتك الأولى لا تحتاج أكثر من دقيقة.</p></div><a class="button" href="{{ route('register') }}">إنشاء حساب طالب</a></div></div></section>
  </main>
  <footer><div class="container footer"><div class="brand"><span class="brand-mark">ن</span><span>مدرسة طموح الإلكترونية<small>لدروس التقوية</small></span></div><p>نرافقك نحو التفوق، أينما كنت.</p><span>© 2026 مدرسة طموح الإلكترونية</span></div></footer>
  <script>
    document.addEventListener('DOMContentLoaded', function () {
      const teachersBox = document.querySelector('#home-teachers');
      const escapeHtml = function (value) {
        const element = document.createElement('div');
        element.textContent = value || '';
        return element.innerHTML;
      };
      const initial = function (name) { return Array.from(name || 'م')[0] || 'م'; };
      fetch('{{ route('api.home-teachers') }}')
        .then(function (response) { return response.json(); })
        .then(function (data) {
          if (!data.ok || !data.teachers.length) {
            teachersBox.innerHTML = '<p>سيتم عرض المدرسين المعتمدين هنا قريبًا.</p>';
            return;
          }
          teachersBox.innerHTML = data.teachers.map(function (teacher) {
            const name = escapeHtml(teacher.full_name);
            const photo = teacher.photo_path
              ? '<img src="/' + escapeHtml(teacher.photo_path.replace(/^public\\//, '')) + '" alt="' + name + '">'
              : '<span>' + initial(teacher.full_name) + '</span>';
            return '<a class="card teacher-card" href="{{ url('/teachers') }}/' + encodeURIComponent(teacher.id) + '" aria-label="عرض ملف ' + name + '">' +
              '<div class="teacher-photo">' + photo + '</div>' +
              '<h3>' + name + '</h3>' +
              '<small>' + escapeHtml(teacher.specialization || 'مدرس معتمد') + '</small>' +
              '<p>' + escapeHtml(teacher.bio || 'مدرس متخصص لمتابعة الطلاب وتبسيط المادة التعليمية.') + '</p>' +
              '<span class="tag">' + escapeHtml(teacher.subjects || 'المواد قريبًا') + '</span>' +
              '</a>';
          }).join('');
        })
        .catch(function () { teachersBox.innerHTML = '<p>تعذر تحميل المدرسين حاليًا.</p>'; });
    });
  </script>
</body>
</html>

